def total(price_cents: int, quantity: int) -> int:
    if type(price_cents) is not int or type(quantity) is not int:
        raise ValueError("integers required")
    if price_cents < 0 or quantity <= 0:
        raise ValueError("invalid price or quantity")
    return price_cents * quantity

print(total(2500, 3))

exercise.solution:
assert total(0, 1) == 0
try:
    total(2500, 0)
except ValueError:
    print("invalid quantity rejected")
else:
    raise AssertionError("zero quantity accepted")

