def index_products(products):
    result = {}
    for product in products:
        key = product["id"]
        if key in result:
            raise ValueError("duplicate id")
        result[key] = product
    return result

products = [{"id": "a", "stock": 3}, {"id": "b", "stock": 0}]
by_id = index_products(products)
print(by_id.get("missing"))
print([p["id"] for p in products if p["stock"] > 0])

exercise.solution:
products.append({"id": "c", "stock": 2})
assert [p["id"] for p in products if p["stock"] > 0] == ["a", "c"]
try:
    index_products(products + [{"id": "a", "stock": 9}])
except ValueError:
    print("duplicate rejected")
else:
    raise AssertionError("duplicate accepted")

