import csv
import io

def parse_catalog(text):
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames != ["sku", "stock"]:
        raise ValueError("expected sku,stock headers")
    accepted, errors = [], []
    for row in reader:
        try:
            if not row["sku"] or None in row:
                raise ValueError("invalid columns")
            stock = int(row["stock"])
            if stock < 0:
                raise ValueError("negative stock")
            accepted.append({"sku": row["sku"], "stock": stock})
        except (ValueError, TypeError) as error:
            errors.append({"line": reader.line_num, "error": str(error)})
    return accepted, errors

accepted, errors = parse_catalog("sku,stock\na,3\nb,no\n")
print(accepted)
print(errors)

from dataclasses import dataclass

@dataclass
class Product:
    sku: str
    stock: int

    def __post_init__(self):
        if type(self.stock) is not int or self.stock < 0:
            raise ValueError("invalid stock")

    def reserve(self, quantity):
        if type(quantity) is not int or not 0 < quantity <= self.stock:
            raise ValueError("unavailable quantity")
        self.stock -= quantity

product = Product("demo", 5)
product.reserve(2)
print(product.stock)

exercise.solution:
try:
    product.reserve(4)
except ValueError:
    pass
else:
    raise AssertionError("overselling accepted")
assert product.stock == 3
